package com.amaury.pointage

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/** PNG design assets embedded in the APK so each visual stays independent. */
object HpDesignAssets {
    private const val CLOCK_FACE_B64 = ""
    private const val HAND_B64 = ""
    private const val SECOND_B64 = ""
    private const val SUN_B64 = ""
    private const val MOON_B64 = ""

    private fun decode(value: String): Bitmap {
        val bytes = Base64.decode(value, Base64.DEFAULT)
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }

    val clockFace by lazy { decode(CLOCK_FACE_B64) }
    val hand by lazy { decode(HAND_B64) }
    val secondHand by lazy { decode(SECOND_B64) }
    val sun by lazy { decode(SUN_B64) }
    val moon by lazy { decode(MOON_B64) }
}
